/// Strict package-authored YAML frontmatter for role definitions (D76 §2.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RoleFrontmatter {
    #[serde(rename = "schema")]
    pub schema: SchemaId,
    /// Role id, for example implementer in D76 §2.2.
    #[serde(rename = "id")]
    pub id: Id,
    #[serde(rename = "version")]
    pub version: u32,
    /// YAML field modes, for example [lane-delivery].
    #[serde(rename = "modes")]
    pub modes: Vec<ModeId>,
    #[serde(rename = "model_slot")]
    pub model_slot: RosterSlot,
    /// Roster thinking value, for example high/max/xhigh.
    #[serde(rename = "thinking")]
    pub thinking: ThinkingLevel,
    /// Exact active tool names supplied in the YAML list.
    #[serde(rename = "tools")]
    pub tools: Vec<ToolName>,
    #[serde(rename = "permissions")]
    pub permissions: RoleFrontmatterPermissions,
    #[serde(rename = "context_policy")]
    pub context_policy: ContractId,
    #[serde(rename = "result_contract")]
    pub result_contract: ContractId,
    #[serde(rename = "checkpoint_contract")]
    pub checkpoint_contract: ContractId,
}

/// Nested generated object.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RoleFrontmatterPermissions {
    #[serde(rename = "repository")]
    pub repository: Permission,
    #[serde(rename = "git")]
    pub git: Permission,
    #[serde(rename = "network")]
    pub network: Permission,
    #[serde(rename = "package_state")]
    pub package_state: Permission,
    #[serde(rename = "operator_checkout")]
    pub operator_checkout: Permission,
}

/// Clean v2 runtime identity namespace (D76 §5.1).
